  if(path==='/api/batteries/reconcile'&&method==='POST'){const uid=await mapCentralUserId(central,actor.id);const before:any=await central.prepare('SELECT COALESCE(MAX(rowid),0) AS cursor FROM battery_transactions WHERE userId=?').bind(uid).first();await reconcileCommentRewards(appDb,central,actor);await reconcileLuckyRewards(appDb,central,actor);const after:any=await central.prepare('SELECT COALESCE(MAX(rowid),0) AS cursor FROM battery_transactions WHERE userId=?').bind(uid).first();return json({success:true,changed:Number(before?.cursor||0)!==Number(after?.cursor||0)});}
  if((path==='/api/batteries/me'||path==='/api/batteries/summary')&&method==='GET'){const quick=path.endsWith('/summary');if(!quick){await reconcileCommentRewards(appDb,central,actor);await reconcileLuckyRewards(appDb,central,actor);}const uid=await mapCentralUserId(central,actor.id),after=Math.max(0,Number(url.searchParams.get('after'))||0);const snapshot:any=await central.prepare(`SELECT COALESCE(SUM(deltaUnits),0) AS balanceUnits,COALESCE(MAX(rowid),0) AS cursor,(SELECT json_group_array(json_object('id',id,'delta',deltaUnits/10.0)) FROM (SELECT id,deltaUnits FROM battery_transactions WHERE userId=? AND rowid>? AND ?>0 AND type NOT IN ('initial','balance_correction') ORDER BY rowid)) AS changes,(SELECT json_group_array(DISTINCT trackId) FROM battery_transactions WHERE userId=? AND type='comment_reward' AND deltaUnits>0 AND trackId IS NOT NULL) AS commentRewardTrackIds FROM battery_transactions WHERE userId=?`).bind(uid,after,after,uid,uid).first();const unread:any=await appDb.prepare('SELECT COUNT(*) AS count FROM member_notifications WHERE userId=? AND readAt IS NULL').bind(actor.id).first();if(quick&&after>0&&Number(snapshot?.cursor||0)===after)return json({unchanged:true,cursor:after,changes:[],unreadNotifications:Number(unread?.count||0),canGrant:canGrantBatteries(actor),isSuperAdmin:isSuperAdmin(actor),canManageRules:canManageRules(actor)});const unlocks=await appDb.prepare('SELECT trackId FROM sticker_unlocks WHERE userId=? AND transactionId IS NOT NULL').bind(actor.id).all();return json({balanceUnits:Number(snapshot?.balanceUnits||0),balance:unitsToBatteries(snapshot?.balanceUnits||0),cursor:Number(snapshot?.cursor||0),changes:parseJson(snapshot?.changes,[]),unlockedTrackIds:(unlocks.results||[]).map((r:any)=>r.trackId),commentRewardTrackIds:parseJson(snapshot?.commentRewardTrackIds,[]),unreadNotifications:Number(unread?.count||0),canGrant:canGrantBatteries(actor),isSuperAdmin:isSuperAdmin(actor),canManageRules:canManageRules(actor),...(quick?{}:await transactionHistory(appDb,central,actor))});}
